:root {
  --ink: #08050f;
  --ink-2: #120a22;
  --cream: #fff1d0;
  --cream-dim: #d9c8aa;
  --coral: #ff5d6c;
  --coral-hot: #ff8a5c;
  --pink: #ff3d91;
  --cyan: #56f2e4;
  --gold: #ffc857;
  --panel: rgba(13, 8, 28, .62);
  --line: rgba(255, 241, 208, .18);
  --display: "Trebuchet MS", "Gill Sans", "Segoe UI", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}

body { overscroll-behavior: none; }

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 4px;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border: 1px solid rgba(255, 241, 208, .3);
  border-bottom-color: rgba(255, 241, 208, .5);
  border-radius: 4px;
  background: rgba(255, 241, 208, .07);
  color: var(--cream);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 2px 0 rgba(0, 0, 0, .3);
}

.is-hidden { display: none !important; }

.game {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
  user-select: none;
  touch-action: none;
  background: #0b0616;
}

#canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(90% 55% at 50% -14%, rgba(255, 86, 111, .26), transparent 62%),
    radial-gradient(70% 80% at 105% 105%, rgba(20, 210, 201, .09), transparent 60%),
    radial-gradient(75% 80% at -5% 70%, rgba(255, 61, 145, .06), transparent 55%);
  mix-blend-mode: screen;
}

.grain {
  position: absolute;
  inset: -50%;
  z-index: 3;
  pointer-events: none;
  opacity: .06;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  background-size: 170px 170px;
  animation: grain-shift .28s steps(2) infinite;
  mix-blend-mode: soft-light;
}

@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.frame {
  position: absolute;
  inset: 14px;
  z-index: 4;
  border: 1px solid rgba(255, 241, 208, .1);
  pointer-events: none;
  box-shadow: inset 0 0 80px rgba(0, 0, 0, .22);
}

.frame::before,
.frame::after {
  content: "";
  position: absolute;
  width: 48px;
  height: 48px;
  border-color: rgba(255, 241, 208, .34);
  border-style: solid;
}

.frame::before { top: -1px; left: -1px; border-width: 1px 0 0 1px; }
.frame::after { bottom: -1px; right: -1px; border-width: 0 1px 1px 0; }

/* ---------- HUD ---------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 8;
  padding: clamp(22px, 3.4vw, 48px);
  pointer-events: none;
  transition: opacity .5s ease, transform .5s ease;
}

.game.is-menu .hud {
  opacity: 0;
  transform: translateY(-8px);
  pointer-events: none;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--cream);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .24em;
  text-transform: uppercase;
  text-shadow: 0 2px 12px rgba(0, 0, 0, .65);
}

.logo em {
  display: inline-flex;
  align-items: center;
  height: 16px;
  margin-left: 2px;
  padding: 0 5px;
  border: 1px solid rgba(255, 241, 208, .25);
  border-radius: 3px;
  color: rgba(255, 241, 208, .58);
  font-family: var(--mono);
  font-size: 8px;
  font-style: normal;
  letter-spacing: .08em;
}

.logo-sun {
  display: inline-block;
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: linear-gradient(180deg, var(--gold) 0 48%, var(--coral) 48% 100%);
  box-shadow: 0 0 12px rgba(255, 106, 101, .9);
}

.stats {
  display: flex;
  align-items: stretch;
  gap: 0;
  margin-top: 12px;
}

.stat {
  min-width: 118px;
  padding: 3px 18px 2px 0;
}

.stat + .stat {
  padding-left: 18px;
  border-left: 1px solid rgba(255, 241, 208, .16);
}

.stat-label {
  display: block;
  margin-bottom: 2px;
  color: rgba(255, 241, 208, .52);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .19em;
}

.stat strong {
  display: flex;
  align-items: baseline;
  gap: 4px;
  color: var(--cream);
  font-family: var(--mono);
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -.06em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 18px rgba(0, 0, 0, .55);
}

.stat strong b { font-weight: 700; }
.stat strong i {
  color: rgba(255, 241, 208, .45);
  font-size: 8px;
  font-style: normal;
  letter-spacing: .12em;
}

.score-stat strong {
  color: var(--gold);
  letter-spacing: .02em;
}

.hud-right {
  display: flex;
  align-items: center;
  gap: 9px;
}

.armor {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  margin-right: 5px;
  padding: 7px 11px 8px;
  border: 1px solid rgba(255, 241, 208, .13);
  border-radius: 5px;
  background: var(--panel);
  backdrop-filter: blur(8px);
}

.armor-label {
  color: rgba(255, 241, 208, .5);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .19em;
}

.armor-pips {
  display: flex;
  gap: 5px;
}

.pip {
  width: 13px;
  height: 9px;
  background: rgba(255, 241, 208, .12);
  clip-path: polygon(18% 0, 100% 0, 82% 100%, 0 100%);
  transition: background .18s ease, box-shadow .18s ease, transform .18s ease;
}

.pip.is-on {
  background: linear-gradient(90deg, var(--gold), var(--coral-hot));
  box-shadow: 0 0 9px rgba(255, 126, 91, .62);
}

.pip.is-hit { transform: scaleY(.4); background: rgba(255, 241, 208, .14); }

.icon-btn {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid rgba(255, 241, 208, .15);
  border-radius: 50%;
  background: var(--panel);
  color: var(--cream);
  backdrop-filter: blur(8px);
  pointer-events: auto;
  transition: border-color .18s ease, background .18s ease, transform .18s ease;
}

.icon-btn:hover {
  border-color: rgba(255, 241, 208, .4);
  background: rgba(30, 16, 45, .8);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn .ico-sound { display: none; }
.icon-btn.is-muted .ico-sound { display: none; }
.icon-btn.is-muted .ico-muted { display: block; }
.icon-btn:not(.is-muted) .ico-muted { display: none; }
.icon-btn:not(.is-muted) .ico-sound { display: block; }
.icon-btn .sound-wave { fill: none; }

.combo {
  position: absolute;
  top: 112px;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 166px;
  opacity: 0;
  transform: translate(-50%, 8px) scale(.96);
  transition: opacity .2s ease, transform .2s ease;
  text-shadow: 0 2px 18px rgba(0, 0, 0, .7);
}

.combo.is-active {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.combo-kicker {
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .22em;
}

.combo strong {
  color: var(--cream);
  font-size: 30px;
  font-weight: 900;
  font-style: italic;
  letter-spacing: -.06em;
  line-height: 1;
}

.combo strong span { color: var(--coral); }

.combo-line {
  width: 100%;
  height: 2px;
  margin-top: 5px;
  overflow: hidden;
  background: rgba(255, 241, 208, .18);
}

.combo-line i {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  transform-origin: left;
}

.callout {
  position: absolute;
  top: 31%;
  left: 50%;
  width: min(80vw, 520px);
  transform: translate(-50%, -50%);
  color: var(--cream);
  font-size: clamp(24px, 3.8vw, 48px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -.025em;
  text-align: center;
  text-transform: uppercase;
  opacity: 0;
  pointer-events: none;
  text-shadow: 0 4px 30px rgba(0, 0, 0, .75), 0 0 30px rgba(255, 109, 96, .3);
}

.callout.is-show { animation: callout-pop 1.15s cubic-bezier(.16, 1, .3, 1) both; }
.callout.is-good { color: var(--cyan); text-shadow: 0 4px 30px rgba(0, 0, 0, .75), 0 0 24px rgba(86, 242, 228, .55); }
.callout.is-warn { color: var(--coral); }

@keyframes callout-pop {
  0% { opacity: 0; transform: translate(-50%, -35%) scale(.82); }
  13% { opacity: 1; transform: translate(-50%, -50%) scale(1.04); }
  22% { transform: translate(-50%, -50%) scale(1); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -68%) scale(.98); }
}

.bottom-hud {
  position: absolute;
  right: clamp(22px, 3.4vw, 48px);
  bottom: clamp(24px, 3.6vw, 42px);
  left: clamp(22px, 3.4vw, 48px);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
}

.nitro-box { width: clamp(150px, 17vw, 232px); }

.nitro-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 7px;
}

.nitro-head span {
  color: rgba(255, 241, 208, .57);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .22em;
}

.nitro-head b {
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .04em;
}

.nitro-track {
  position: relative;
  height: 7px;
  overflow: hidden;
  border: 1px solid rgba(86, 242, 228, .26);
  background: rgba(7, 20, 27, .54);
  clip-path: polygon(0 0, 100% 0, calc(100% - 7px) 100%, 0 100%);
}

.nitro-fill {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #2bb9b7, var(--cyan) 73%, #eaffd8);
  box-shadow: 0 0 16px rgba(86, 242, 228, .72);
  transform-origin: left;
  transition: transform .12s linear;
}

.nitro-sheen {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 21px, rgba(7, 20, 27, .62) 21px 23px);
  pointer-events: none;
}

.nitro-hint {
  display: block;
  margin-top: 6px;
  color: rgba(255, 241, 208, .3);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .18em;
}

.speed-box {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  width: clamp(168px, 16vw, 214px);
}

.speed-read {
  display: flex;
  align-items: flex-end;
  gap: 7px;
  line-height: .74;
  text-shadow: 0 4px 32px rgba(0, 0, 0, .7);
}

.speed-read > span {
  min-width: 3ch;
  color: var(--cream);
  font-family: var(--mono);
  font-size: clamp(43px, 5.2vw, 68px);
  font-weight: 700;
  letter-spacing: -.11em;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.speed-read small {
  padding-bottom: 6px;
  color: var(--coral-hot);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .15em;
  white-space: nowrap;
}

.speed-track {
  width: 100%;
  height: 3px;
  margin-top: 11px;
  background: rgba(255, 241, 208, .16);
}

.speed-track i {
  display: block;
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--gold), var(--coral));
  box-shadow: 0 0 10px rgba(255, 100, 86, .7);
  transition: width .12s linear;
}

.speed-caption {
  margin-top: 6px;
  color: rgba(255, 241, 208, .3);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .2em;
}

.speed-caption b { color: rgba(255, 241, 208, .58); font-weight: 700; }

.key-hints {
  position: absolute;
  bottom: 30px;
  left: 50%;
  display: flex;
  gap: 18px;
  transform: translateX(-50%);
  color: rgba(255, 241, 208, .38);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .13em;
  white-space: nowrap;
}

.key-hints span { display: flex; align-items: center; gap: 5px; }
.key-hints kbd { height: 18px; min-width: 18px; font-size: 8px; }

/* ---------- Touch controls ---------- */

.touch-controls {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(20px, env(safe-area-inset-bottom));
  left: max(18px, env(safe-area-inset-left));
  z-index: 9;
  display: none;
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
}

.touch-steer,
.touch-actions {
  display: flex;
  align-items: flex-end;
  gap: 10px;
}

.touch-btn {
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
  border: 1px solid rgba(255, 241, 208, .2);
  border-radius: 50%;
  background: rgba(12, 7, 26, .54);
  color: var(--cream);
  backdrop-filter: blur(8px);
  pointer-events: auto;
  touch-action: none;
  transition: transform .1s ease, background .1s ease, border-color .1s ease;
}

.touch-btn svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.touch-btn span {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .04em;
}

.touch-btn.is-down {
  transform: scale(.92);
  border-color: rgba(86, 242, 228, .65);
  background: rgba(33, 95, 97, .44);
}

.nitro-btn {
  width: 76px;
  height: 76px;
  border-color: rgba(86, 242, 228, .38);
  color: var(--cyan);
  box-shadow: 0 0 28px rgba(86, 242, 228, .1), inset 0 0 18px rgba(86, 242, 228, .06);
}

.brake-btn {
  width: 54px;
  height: 54px;
  color: rgba(255, 241, 208, .65);
  font-size: 9px;
}

/* ---------- Screens ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(22px, 3.4vw, 48px);
  overflow: hidden;
  pointer-events: auto;
}

.start-screen {
  background:
    linear-gradient(90deg, rgba(7, 4, 15, .69) 0%, rgba(7, 4, 15, .25) 50%, rgba(7, 4, 15, 0) 72%),
    linear-gradient(0deg, rgba(7, 4, 15, .74) 0%, transparent 32%);
}

.start-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(60% 70% at 80% 48%, transparent 25%, rgba(8, 4, 16, .34) 100%);
}

.start-top {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: rgba(255, 241, 208, .55);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
}

.mini-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--cream);
  font-size: 10px;
  letter-spacing: .22em;
}

.start-meta { display: flex; align-items: center; gap: 10px; }
.start-meta i { width: 4px; height: 4px; border-radius: 50%; background: var(--coral); box-shadow: 0 0 9px var(--coral); }

.hero {
  position: relative;
  z-index: 3;
  width: min(720px, 58vw);
  margin-top: auto;
  margin-bottom: auto;
  padding-bottom: 2vh;
  transform: translateY(-2vh);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: clamp(15px, 2vw, 26px);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 10px);
  font-weight: 700;
  letter-spacing: .23em;
  text-shadow: 0 0 18px rgba(86, 242, 228, .4);
  animation: rise .8s .08s cubic-bezier(.16, 1, .3, 1) both;
}

.eyebrow-line { width: 34px; height: 1px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }

.hero h1 {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin: 0 0 clamp(20px, 2.6vw, 32px);
  color: var(--cream);
  font-size: clamp(62px, 10.4vw, 150px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -.075em;
  line-height: .68;
  text-transform: uppercase;
  text-shadow: 0 8px 70px rgba(0, 0, 0, .5);
  animation: rise .9s .14s cubic-bezier(.16, 1, .3, 1) both;
}

.title-outline {
  position: relative;
  padding-right: .12em;
  color: transparent;
  -webkit-text-stroke: clamp(1px, .13vw, 2px) var(--coral);
  text-shadow: 0 0 48px rgba(255, 78, 109, .25);
}

.title-outline::after {
  content: "RUN";
  position: absolute;
  inset: 0;
  z-index: -1;
  color: var(--coral);
  filter: blur(24px);
  opacity: .38;
}

.hero-copy {
  max-width: 460px;
  margin: 0 0 clamp(22px, 3vw, 36px);
  color: rgba(255, 241, 208, .7);
  font-size: clamp(12px, 1.1vw, 15px);
  line-height: 1.7;
  letter-spacing: .005em;
  text-shadow: 0 2px 16px rgba(0, 0, 0, .6);
  animation: rise .9s .23s cubic-bezier(.16, 1, .3, 1) both;
}

.start-row {
  display: flex;
  align-items: stretch;
  gap: 14px;
  animation: rise .9s .32s cubic-bezier(.16, 1, .3, 1) both;
}

.start-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-width: 194px;
  height: 58px;
  padding: 0 26px;
  overflow: hidden;
  border: 1px solid rgba(255, 205, 144, .3);
  border-radius: 4px;
  background: linear-gradient(135deg, var(--coral-hot), var(--coral) 48%, #e83e73);
  color: #190811;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: .15em;
  box-shadow: 0 12px 38px rgba(255, 76, 98, .22), inset 0 1px 0 rgba(255, 244, 210, .55);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s ease;
}

.start-btn::before {
  content: "";
  position: absolute;
  top: -120%;
  left: -40%;
  width: 36%;
  height: 340%;
  background: rgba(255, 247, 220, .32);
  transform: rotate(23deg);
  transition: left .45s ease;
}

.start-btn:hover {
  filter: brightness(1.06);
  transform: translateY(-2px);
  box-shadow: 0 16px 46px rgba(255, 76, 98, .32), inset 0 1px 0 rgba(255, 244, 210, .55);
}

.start-btn:hover::before { left: 115%; }
.start-btn:active { transform: translateY(0); }

.start-btn svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.best-badge {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 142px;
  padding: 0 17px;
  border: 1px solid rgba(255, 241, 208, .16);
  border-radius: 4px;
  background: rgba(9, 5, 19, .42);
  backdrop-filter: blur(8px);
}

.best-badge span {
  margin-bottom: 2px;
  color: rgba(255, 241, 208, .46);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .18em;
}

.best-badge strong {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 17px;
  letter-spacing: .03em;
  font-variant-numeric: tabular-nums;
}

.menu-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: clamp(18px, 2.5vw, 28px);
  color: rgba(255, 241, 208, .34);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .13em;
  animation: rise .9s .4s cubic-bezier(.16, 1, .3, 1) both;
}

.menu-controls .dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(255, 241, 208, .34);
}

.menu-controls kbd { height: 19px; min-width: 19px; margin: 0 1px; font-size: 7px; }

.start-footer {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  color: rgba(255, 241, 208, .34);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .16em;
}

.radio { display: flex; align-items: center; gap: 9px; }
.radio-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 10px var(--coral);
  animation: blink 1.8s ease-in-out infinite;
}

@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

.start-tip { color: rgba(255, 241, 208, .43); }
.edition { display: flex; align-items: center; gap: 7px; }
.edition b { color: var(--cream); font-size: 8px; }

.decor-sun {
  position: absolute;
  top: 7%;
  right: 4.5vw;
  z-index: 1;
  width: clamp(260px, 35vw, 520px);
  aspect-ratio: 1;
  border-radius: 50%;
  opacity: .92;
  background: linear-gradient(180deg, #ffd27a 0%, #ff9c59 32%, #ff5b72 64%, #c72d72 100%);
  -webkit-mask-image: repeating-linear-gradient(180deg, #000 0 7px, transparent 7px 12px);
  mask-image: repeating-linear-gradient(180deg, #000 0 7px, transparent 7px 12px);
  filter: blur(.3px) drop-shadow(0 0 70px rgba(255, 84, 106, .3));
  pointer-events: none;
}

.decor-sun::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  box-shadow: inset 0 0 80px rgba(82, 8, 43, .35);
}

@keyframes rise {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- Modal screens ---------- */

.dim-screen {
  align-items: center;
  justify-content: center;
  background: rgba(5, 3, 12, .57);
  backdrop-filter: blur(9px) saturate(.82);
  animation: fade-in .28s ease both;
}

@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

.modal {
  position: relative;
  width: min(540px, calc(100vw - 40px));
  padding: clamp(26px, 3.8vw, 44px);
  border: 1px solid rgba(255, 241, 208, .16);
  border-radius: 6px;
  background:
    linear-gradient(145deg, rgba(29, 15, 42, .93), rgba(9, 5, 19, .96) 64%),
    radial-gradient(80% 80% at 100% 0, rgba(255, 94, 104, .1), transparent 60%);
  box-shadow: 0 40px 110px rgba(0, 0, 0, .7), inset 0 1px 0 rgba(255, 241, 208, .12);
  animation: modal-in .42s cubic-bezier(.16, 1, .3, 1) both;
}

.modal::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 12%;
  width: 28%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--coral), transparent);
  box-shadow: 0 0 15px var(--coral);
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(20px) scale(.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 8px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .22em;
}

.modal-kicker span {
  width: 24px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
}

.modal h2 {
  margin: 0;
  color: var(--cream);
  font-size: clamp(47px, 6.2vw, 74px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -.065em;
  line-height: .9;
  text-transform: uppercase;
}

.modal h2 span { color: var(--coral); }

.modal-copy {
  margin: 10px 0 26px;
  color: rgba(255, 241, 208, .48);
  font-size: 12px;
  line-height: 1.6;
}

.result-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  overflow: hidden;
  margin-bottom: 22px;
  border: 1px solid rgba(255, 241, 208, .12);
  border-radius: 4px;
  background: rgba(255, 241, 208, .1);
}

.result-grid > div {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 15px 16px;
  background: rgba(9, 5, 19, .84);
}

.result-grid span {
  color: rgba(255, 241, 208, .4);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .18em;
}

.result-grid strong {
  display: flex;
  align-items: baseline;
  gap: 4px;
  color: var(--cream);
  font-family: var(--mono);
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.result-grid strong b { font-weight: 700; }
.result-grid strong i {
  color: rgba(255, 241, 208, .42);
  font-size: 8px;
  font-style: normal;
  letter-spacing: .1em;
}

.result-grid > div:nth-child(1) strong { color: var(--gold); }

.new-best {
  margin: -7px 0 20px;
  padding: 9px 12px;
  border: 1px solid rgba(255, 200, 87, .28);
  border-radius: 3px;
  background: rgba(255, 200, 87, .07);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .14em;
  text-align: center;
}

.new-best span { opacity: .7; }

.modal-actions { display: flex; align-items: stretch; gap: 10px; }
.modal-actions .start-btn { min-width: 184px; height: 52px; font-size: 11px; }

.ghost-btn {
  min-width: 126px;
  height: 52px;
  padding: 0 17px;
  border: 1px solid rgba(255, 241, 208, .16);
  border-radius: 4px;
  background: rgba(255, 241, 208, .03);
  color: rgba(255, 241, 208, .54);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .14em;
  transition: border-color .16s ease, color .16s ease, background .16s ease;
}

.ghost-btn:hover {
  border-color: rgba(255, 241, 208, .4);
  background: rgba(255, 241, 208, .07);
  color: var(--cream);
}

.pause-modal { width: min(440px, calc(100vw - 40px)); }
.pause-modal .modal-copy { margin-bottom: 24px; }
.pause-hint {
  margin-top: 18px;
  color: rgba(255, 241, 208, .32);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .15em;
  text-align: center;
}

.flash {
  position: absolute;
  inset: 0;
  z-index: 15;
  background: radial-gradient(circle at 50% 58%, rgba(255, 243, 216, .28), transparent 42%);
  opacity: 0;
  pointer-events: none;
}

.flash.is-on { animation: flash-bang .55s ease-out both; }

@keyframes flash-bang {
  0% { opacity: 0; }
  12% { opacity: 1; }
  100% { opacity: 0; }
}

/* ---------- Responsive ---------- */

@media (max-width: 900px) {
  .hero { width: min(660px, 70vw); }
  .decor-sun { right: -5vw; opacity: .65; }
  .key-hints { display: none; }
}

@media (max-width: 820px) {
  .touch-controls { display: flex; }

  .hud { padding: 18px 17px; }
  .hud-top { align-items: flex-start; }
  .logo em { display: none; }
  .logo { font-size: 8px; letter-spacing: .18em; }
  .stats { margin-top: 9px; }
  .stat { min-width: 88px; padding-right: 12px; }
  .stat + .stat { padding-left: 12px; }
  .stat strong { font-size: 17px; }
  .stat-label { font-size: 6px; }
  .armor { margin-right: 1px; padding: 5px 8px 6px; }
  .armor-label { font-size: 6px; }
  .pip { width: 10px; height: 7px; }
  .icon-btn { width: 35px; height: 35px; }
  .icon-btn svg { width: 14px; height: 14px; }
  .hud-right { gap: 6px; }

  .combo { top: 90px; width: 130px; }
  .combo strong { font-size: 25px; }
  .callout { top: 27%; }

  .bottom-hud {
    right: 17px;
    bottom: max(104px, calc(env(safe-area-inset-bottom) + 94px));
    left: 17px;
    align-items: flex-end;
  }
  .nitro-box { width: 118px; }
  .nitro-hint { display: none; }
  .nitro-head { margin-bottom: 5px; }
  .nitro-head span { font-size: 7px; }
  .nitro-head b { font-size: 8px; }
  .nitro-track { height: 6px; }
  .speed-box { width: 104px; }
  .speed-read > span { font-size: 38px; }
  .speed-read small { padding-bottom: 3px; font-size: 6px; }
  .speed-track { margin-top: 7px; }
  .speed-caption { display: none; }

  .touch-controls { bottom: max(18px, env(safe-area-inset-bottom)); }
  .touch-btn { width: 58px; height: 58px; }
  .nitro-btn { width: 68px; height: 68px; }
  .brake-btn { width: 48px; height: 48px; }

  .screen { padding: 20px 18px max(18px, env(safe-area-inset-bottom)); }
  .start-screen { background: linear-gradient(0deg, rgba(7, 4, 15, .86) 0%, rgba(7, 4, 15, .22) 62%, rgba(7, 4, 15, .16) 100%); }
  .hero {
    width: 100%;
    margin-top: auto;
    margin-bottom: auto;
    padding-bottom: 0;
    transform: none;
  }
  .hero h1 { font-size: clamp(60px, 21vw, 104px); line-height: .72; margin-bottom: 22px; }
  .hero-copy { max-width: 330px; font-size: 11px; line-height: 1.65; margin-bottom: 24px; }
  .hero-copy br { display: none; }
  .eyebrow { font-size: 7px; letter-spacing: .18em; margin-bottom: 18px; }
  .start-row { gap: 9px; }
  .start-btn { min-width: 150px; height: 52px; gap: 12px; padding: 0 18px; font-size: 11px; }
  .best-badge { min-width: 112px; padding: 0 12px; }
  .best-badge span { font-size: 6px; }
  .best-badge strong { font-size: 14px; }
  .menu-controls { flex-wrap: wrap; gap: 7px; margin-top: 16px; font-size: 6px; }
  .menu-controls kbd { height: 17px; min-width: 17px; font-size: 6px; }
  .start-footer { justify-content: space-between; font-size: 6px; }
  .start-tip { display: none; }
  .start-meta { display: none; }
  .decor-sun { top: 9%; right: -26vw; width: 68vw; opacity: .5; }
  .frame { inset: 8px; }

  .modal { width: min(430px, calc(100vw - 28px)); padding: 25px 22px; }
  .modal h2 { font-size: 54px; }
  .modal-copy { font-size: 11px; margin-bottom: 20px; }
  .result-grid > div { padding: 12px; }
  .result-grid strong { font-size: 21px; }
  .modal-actions { flex-direction: column; }
  .modal-actions .start-btn, .ghost-btn { width: 100%; min-width: 0; height: 50px; }
}

@media (max-width: 430px) {
  .logo { font-size: 7px; }
  .logo-sun { width: 10px; height: 10px; }
  .stat { min-width: 78px; }
  .stat strong { font-size: 15px; }
  .score-stat strong { font-size: 15px; }
  .icon-btn { width: 32px; height: 32px; }
  .armor { padding: 4px 6px 5px; }
  .pip { width: 8px; height: 6px; }
  .touch-btn { width: 54px; height: 54px; }
  .nitro-btn { width: 64px; height: 64px; }
  .brake-btn { width: 44px; height: 44px; }
  .touch-steer, .touch-actions { gap: 8px; }
  .start-btn { min-width: 138px; }
}

@media (max-height: 660px) and (orientation: landscape) {
  .touch-controls { display: none; }
  .touch-btn { width: 48px; height: 48px; }
  .hud { padding: 14px 18px; }
  .stats { margin-top: 6px; }
  .logo { display: none; }
  .combo { top: 76px; }
  .bottom-hud { bottom: 16px; }
  .nitro-box { width: 132px; }
  .speed-box { width: 130px; }
  .speed-read > span { font-size: 38px; }
  .start-screen { background: linear-gradient(90deg, rgba(7, 4, 15, .8) 0%, rgba(7, 4, 15, .2) 70%, transparent); }
  .hero { width: 60vw; transform: none; }
  .hero h1 { font-size: clamp(46px, 9vh, 86px); margin-bottom: 14px; }
  .hero-copy { display: none; }
  .eyebrow { margin-bottom: 12px; }
  .menu-controls { margin-top: 12px; }
  .start-footer { display: none; }
  .decor-sun { width: 42vh; top: 4%; right: 7vw; }
  .modal { padding: 22px 28px; width: min(480px, 80vw); }
  .modal h2 { font-size: 44px; }
  .modal-copy { margin: 6px 0 16px; }
  .result-grid { margin-bottom: 15px; }
  .result-grid > div { padding: 9px 12px; }
  .modal-actions { flex-direction: row; }
  .modal-actions .start-btn, .ghost-btn { height: 44px; }
  .pause-hint { display: none; }
}

@media (pointer: coarse) {
  .key-hints { display: none; }
  .menu-controls { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .grain { animation: none; }
  .eyebrow, .hero h1, .hero-copy, .start-row, .menu-controls { animation-duration: .01s; }
  .radio-dot { animation: none; }
