];

const LANES = [-0.4, -0.2, 0, 0.2, 0.4];
const BEST_KEY = 'sunsetRunBestV1';

let renderer;
let audio;
let score = 0;
let best = loadBest();
let nearMisses = 0;
let passedCars = 0;
let topSpeed = 0;
let combo = 0;
let comboTimer = 0;
let spawnTimer = 0.2;
